{
  "quiz": [
    {
      "key_point": "L25/P06/K1",
      "reason": "This question tests the core application of perceptual psychology in XR system design.",
      "type": "multiple_choice",
      "stem": "How can studying perceptual psychology benefit the design of XR systems?",
      "correct": "It helps inform both better hardware design and anticipating user side effects.",
      "wrong": [
        "It only provides historical context for digital display technology.",
        "It helps maximize processing speed within the computer unit.",
        "It simplifies the initial programming interface for developers."
      ],
      "explanation_correct": "Perceptual psychology offers guidelines for creating better hardware and understanding the impact of the system on the user.",
      "explanations_wrong": [
        "Perceptual psychology goes beyond history to provide actionable guidelines for design.",
        "Its focus is on how the user processes information, not maximizing internal hardware speed.",
        "It concerns how the user perceives the environment, not simplifying the underlying code or interfaces."
      ]
    }
  ],
  "recap": "Perceptual psychology provides crucial guidelines for developing effective XR systems, allowing us to build better hardware and minimize negative effects on the user. To apply this science, designers must understand the basic physiology of the human body and the key theories governing how perception works. Furthermore, it requires analyzing how engineered XR systems might interfere with our normal perceptual processes.",
  "review": [
    {
      "key_point": "L25/P06/K2",
      "question": "What are the three fundamental areas of knowledge needed when investigating how XR systems interact with human perception?",
      "answer": "The necessary areas include understanding basic human physiology, reviewing the core theories of experimental perception, and analyzing how the engineered system might interfere with common perceptual processes."
    }
  ]
}

{
  "quiz": [
    {
      "key_point": "L16/P02/K4",
      "reason": "This item tests the relationship between environment tracking and the purpose (AR vs VR) for which it is used.",
      "type": "multiple_choice",
      "stem": "In Augmented Reality (AR), what is the primary function of tracking the surrounding environment?",
      "correct": "To allow digital content to be accurately superimposed and registered in the real world.",
      "wrong": [
        "To provide the user with alerts about physical hazards they might encounter.",
        "To help map out the boundaries of the virtual experience for the user.",
        "To track physical objects solely for use in telepresence applications."
      ],
      "explanation_correct": "Tracking the environment in AR ensures that digital overlays match up correctly with the real-world position of objects.",
      "explanations_wrong": [
        "Alerts about hazards are a VR safety function, not the primary AR function.",
        "Mapping boundaries relates to system design, not the fundamental use of tracked objects in AR.",
        "Telepresence is one application, but registration is the core purpose in AR."
      ]
    },
    {
      "key_point": "L16/P02/K3",
      "reason": "This item tests the understanding of why 'other body parts' need tracking, focusing on the desired output in the virtual world.",
      "type": "true_false",
      "stem": "Tracking a user's non-sense organ body parts is primarily necessary to ensure that virtual hands and avatars accurately reflect the user's real-world movements.",
      "correct": "True",
      "wrong": [
        "False"
      ],
      "explanation_correct": "Tracking other body parts is required when the user wants a virtual representation (like an avatar or hand) that reproduces their physical actions.",
      "explanations_wrong": [
        "This is incorrect because tracking sense organs, like the eyes, is what is most critical for simple visual VR tracking."
      ]
    },
    {
      "key_point": "L16/P02/K2",
      "reason": "This item tests the critical dependency of VR displays on tracking the user's sense organs (like head movement).",
      "type": "yes_no",
      "stem": "If a display is attached to a sense organ, does its change in position require tracking that organ's orientation to reflect correctly in the virtual world?",
      "correct": "Yes",
      "wrong": [
        "No"
      ],
      "explanation_correct": "Tracking the position and orientation of sense organs is necessary to ensure that attached displays change appropriately with the user's physical movement.",
      "explanations_wrong": [
        "No tracking is needed because the display is intrinsically linked to the organ itself."
      ]
    }
  ],
  "recap": "Tracking systems are broadly divided into three categories: sense organs, non-sense organ body parts, and the surrounding environment. Tracking sense organs, like the head, is essential for linking displays to the user's movement in VR. Meanwhile, tracking other body parts allows the virtual world to accurately represent human actions such as gestures, and environmental tracking provides vital functionality for both virtual safety and digital content registration in AR.",
  "review": [
    {
      "key_point": "L16/P02/K1",
      "question": "What is the difference between tracking a sense organ and tracking another body part?",
      "answer": "Sense organs include eyes and ears, whose movement is controlled by the body and directly affects perception. Other body parts are tracked to provide a virtual representation of the user, such as in an avatar."
    },
    {
      "key_point": "L16/P02/K3",
      "question": "Besides complex tracking mechanisms, how can the need for representing body parts be simplified in certain applications?",
      "answer": "Some systems can simplify the process by requiring the user to send a single input signal, like pressing a button, to change to a predetermined body configuration."
    }
  ]
}

{
  "quiz": [
