    {
      "key_point": "L22/P04/K1",
      "question": "What is the fundamental factor used to classify and divide different AR software tools and packages?",
      "answer": "The primary criteria is the level of programming skill that a user must possess to successfully utilize or modify the software. This factor separates simple, pre-built tools from complex, foundational frameworks."
    }
  ]
}

